def compute(vars):
    cash_proceeds_millions = vars["v1"]
    warrants_exercised = vars["v2"]

    if warrants_exercised == 0:
        return None

    cash_proceeds = cash_proceeds_millions * 1000000
    share_price = cash_proceeds / warrants_exercised

    return {
        "value": share_price,
        "trace": {
            "cash_proceeds_millions": cash_proceeds_millions,
            "cash_proceeds": cash_proceeds,
            "warrants_exercised": warrants_exercised,
            "share_price": share_price,
            "output_meta": {
                "currency": "USD",
                "scale": "ones",
                "unit": "dollars per warrant"
            }
        }
    }
